    @classmethod
    def summary(cls) -> dict:
        return {
            'total_notes_created': {
                'total': cls.total_booknotes(),
                'month': cls.total_booknotes(since=DATE_ONE_MONTH_AGO),
                'week': cls.total_booknotes(since=DATE_ONE_WEEK_AGO),
            },
            'total_note_takers': {
                'total': cls.total_unique_users(),
